    {
      "campo": "resolucao.antes.simbolos",
      "depois": [
        ["µ", "densidade linear de massa: massa da corda por metro de comprimento"],
        ["T", "força de tração que estica a corda"],
        ["λ", "comprimento de onda: distância de uma onda completa"],
        ["f", "frequência: quantas oscilações por segundo"],
        ["v", "velocidade com que a onda se propaga na corda"],
        ["ventre", "ponto da corda que balança com a maior amplitude"],
        ["modo fundamental", "vibração mais simples da corda, com um só ventre entre as duas pontas fixas"],
        ["∝", "'é proporcional a': se um dobra, o outro dobra"]
      ],
      "motivo": "Faltavam v, ventre e ∝, usados na resolução."
    },
    {
      "campo": "resolucao.passos[2].conta",
      "depois": "v' = √(T/(4µ)) = (1/2) × √(T/µ) = v/2",
      "motivo": "Mostra a passagem da raiz, sem pular."
    },
    {
      "campo": "resolucao.erradas.E",
      "depois": "f₀/8 não confere: exigiria v cair 8 vezes, o que pediria µ × 64. Quem marcou pode ter somado os erros: dividiu por 4 e depois por 2. Com µ × 4, v cai só √4 = 2 vezes, e f₀/2 é o resultado.",
      "motivo": "Diz o que faltou no raciocínio de quem marcou E, com teste objetivo (8² = 64)."
    },
    {
      "campo": "resolucao.erradas.C",
      "depois": "4f₀ tem dois erros: o sentido está invertido (µ maior deixa a onda mais lenta, f diminui) e a raiz foi esquecida. O certo é dividir por √4 = 2.",
      "motivo": "Frase mais direta."
    }
  ],
